    public void journey(String action,JSONObject data,Callback callback){execute((u,t,c)->{
        try{return write("/rest/v1/rpc/clt_journey","POST",new JSONObject().put("p_action",action).put("p_data",data),t,c);}
        catch(MissingRpcException e){if(!action.equals("stats"))throw new IOException("O progresso ainda precisa ser ativado no banco. Execute BatCaverna-1.2.0-Supabase.sql inteiro no SQL Editor do Supabase e tente novamente.");JSONArray all=new JSONArray();for(int offset=0;offset<20000;offset+=250){JSONArray page=get("/rest/v1/itens?select=id,categoria,tipo,status,horas,data&user_id=eq."+encode(u)+"&order=id.asc&limit=250&offset="+offset,t,c);for(int i=0;i<page.length();i++)all.put(page.optJSONObject(i));if(page.length()<250)return new JSONArray().put(NativeStatistics.calculate(all,System.currentTimeMillis()));}throw new IOException("Biblioteca extensa demais para calcular completamente.");}
    },callback);}
