    public void socialHome(Callback callback){execute((user,token,config)->{JSONArray friends=get("/rest/v1/amigos?select=*&user_id=eq."+user+"&order=amigo_id.asc&limit=1000",token,config);if(friends.length()==0)return new JSONArray().put(new JSONObject().put("friends",new JSONArray()).put("activity",new JSONArray()));String ids=ids(friends,"amigo_id");JSONArray profiles=get("/rest/v1/perfis_publicos_clt?select=id,nome,avatar_url&id=in."+encode(ids)+"&limit=1000",token,config);SharedPreferences prefs=SessionPreferences.get(context);java.util.Map<String,Long> since=new java.util.HashMap<>();for(int i=0;i<friends.length();i++){JSONObject f=friends.getJSONObject(i);String id=f.optString("amigo_id"),key="native_friend_since:"+user+":"+id;long stamp=MessageTime.epoch(f.optString("created_at",f.optString("aceito_em",f.optString("accepted_at",""))));if(stamp<=0)stamp=prefs.getLong(key,System.currentTimeMillis());since.put(id,stamp);if(token.equals(prefs.getString("access_token","")))prefs.edit().putLong(key,stamp).apply();}String min=new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'",java.util.Locale.ROOT){{setTimeZone(java.util.TimeZone.getTimeZone("UTC"));}}.format(new java.util.Date(System.currentTimeMillis()-7*86400000L));JSONArray source=get("/rest/v1/clt_activity_events?select=id,user_id,item_id,categoria,nome,status,created_at&user_id=in."+encode(ids)+"&created_at=gte."+encode(min)+"&order=created_at.desc,id.desc&limit=100",token,config),activity=new JSONArray();java.util.Set<String> seen=new java.util.HashSet<>();for(int i=0;i<source.length()&&activity.length()<12;i++){JSONObject event=source.getJSONObject(i);Long start=since.get(event.optString("user_id"));String key=event.optString("user_id")+":"+event.optString("categoria")+":"+event.optString("item_id",event.optString("nome"));if(start!=null&&SocialActivityPolicy.recent(MessageTime.epoch(event.optString("created_at")),start,System.currentTimeMillis())&&seen.add(key))activity.put(event);}return new JSONArray().put(new JSONObject().put("friends",profiles).put("activity",withAuthors(activity,token,config)));},callback);}
    private static final ExecutorService STEAM_QUEUE=Executors.newSingleThreadExecutor(),MEDIA_QUEUE=Executors.newSingleThreadExecutor();
    private static final ExecutorService STEAM_IO=Executors.newFixedThreadPool(4);
    public void currentSteam(Callback callback){execute((user,token,config)->{JSONObject own=get("/rest/v1/perfis?select=steam_id&id=eq."+user+"&limit=1",token,config).getJSONObject(0);String steam=own.optString("steam_id","");if(!steam.matches("[0-9]{17}"))return new JSONArray();JSONObject game=steamRequest("agora",steam,token,config).optJSONObject("jogando");return game==null?new JSONArray():new JSONArray().put(game);},callback,STEAM_QUEUE);}
    public void steamFriends(Callback callback){execute((user,token,config)->{JSONArray ids=get("/rest/v1/amigos?select=amigo_id&user_id=eq."+user+"&order=amigo_id.asc&limit=20",token,config);if(ids.length()==0)return new JSONArray().put(new JSONObject().put("games",new JSONArray()).put("failed",0));JSONArray people=get("/rest/v1/perfis?select=id,nome,steam_id&id=in."+encode(ids(ids,"amigo_id"))+"&limit=20",token,config);java.util.List<java.util.concurrent.Future<JSONObject>> tasks=new java.util.ArrayList<>();for(int i=0;i<people.length();i++){JSONObject p=people.getJSONObject(i);String steam=p.optString("steam_id","");if(!steam.matches("[0-9]{17}"))continue;tasks.add(STEAM_IO.submit(()->{JSONObject reply=steamRequest("agora",steam,token,config),game=reply.optJSONObject("jogando");if(game==null)return null;return new JSONObject().put("friend_id",p.optString("id")).put("name",p.optString("nome")).put("game",game.optString("nome","Jogando na Steam")).put("appid",game.optString("appid")).put("cover",game.optString("capa",""));}));}JSONArray games=new JSONArray();int failures=0;for(java.util.concurrent.Future<JSONObject> task:tasks)try{JSONObject game=task.get(20,TimeUnit.SECONDS);if(game!=null)games.put(game);}catch(Exception e){failures++;task.cancel(true);}return new JSONArray().put(new JSONObject().put("games",games).put("failed",failures));},callback,STEAM_QUEUE);}
    private static JSONObject steamRequest(String op,String id,String token,String[] config)throws Exception{HttpURLConnection conn=(HttpURLConnection)new URL(config[0]+"/functions/v1/bright-api").openConnection();try{conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(7000);conn.setReadTimeout(10000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("apikey",config[1]);conn.setRequestProperty("Authorization","Bearer "+token);conn.setRequestProperty("Content-Type","application/json");try(OutputStream out=conn.getOutputStream()){out.write(new JSONObject().put("op",op).put("steamid",id).toString().getBytes(StandardCharsets.UTF_8));}if(conn.getResponseCode()!=200)throw new IOException("Steam indisponível.");JSONObject value=new JSONObject(read(conn.getInputStream()));if(value.has("erro"))throw new IOException("Steam indisponível.");return value;}finally{conn.disconnect();}}
    private static JSONObject brightRequest(JSONObject input,String token,String[] config)throws Exception{
        HttpURLConnection conn=(HttpURLConnection)new URL(config[0]+"/functions/v1/bright-api").openConnection();
        try{conn.setConnectTimeout(10000);conn.setReadTimeout(40000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("apikey",config[1]);conn.setRequestProperty("Authorization","Bearer "+token);conn.setRequestProperty("Content-Type","application/json");try(OutputStream out=conn.getOutputStream()){out.write(input.toString().getBytes(StandardCharsets.UTF_8));}int status=conn.getResponseCode();JSONObject reply=new JSONObject(read(status<400?conn.getInputStream():conn.getErrorStream()));if(BrightResponsePolicy.failed(status,reply))throw new IOException(ApiErrorPolicy.message(reply.optString("code",""),status==200?400:status));return reply;}finally{conn.disconnect();}
    }
    public void steamLookup(String name,Callback cb){execute((u,t,c)->{
        JSONObject detail=igdbGame(name,t);long appid=detail.optLong("steam_appid");if(appid<=0)throw new IOException("O IGDB não tem um vínculo Steam inequívoco. Informe o App ID manualmente.");return new JSONArray().put(new JSONObject().put("steamAppid",appid).put("nome",detail.optString("name")));
    },cb);}
    private JSONObject igdbGame(String name,String token)throws Exception{
        JSONObject search=catalogObject("igdb/games?search="+encode(name),token);JSONArray rows=search.optJSONArray("results");JSONObject selected=null;
        for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(catalogTitleKey(name).equals(catalogTitleKey(row.optString("name")))){if(selected!=null)throw new IOException("Selecione a edição correta no catálogo IGDB.");selected=row;}}
        if(selected==null)throw new IOException("Sem correspondência exata no catálogo IGDB.");return catalogObject("igdb/games/"+selected.optLong("id"),token);
    }
    public void retroRequest(JSONObject input,Callback cb){execute((u,t,c)->new JSONArray().put(brightRequest(input,t,c)),cb);}
    public void retro(Callback cb){execute((u,t,c)->{
        JSONObject p=get("/rest/v1/perfis?select=retroachievements_user&id=eq."+u+"&limit=1",t,c).getJSONObject(0);String name=p.optString("retroachievements_user","");
        if(name.isEmpty()||name.equals("null"))throw new IOException("Conecte seu usuário RetroAchievements nas integrações do desktop.");
        JSONObject profile=brightRequest(new JSONObject().put("op","raPerfil").put("usuario",name),t,c),games=brightRequest(new JSONObject().put("op","raJogos").put("usuario",name),t,c),collection=brightRequest(new JSONObject().put("op","raCollection"),t,c);
        JSONArray rows=games.optJSONArray("jogos"),ids=collection.optJSONArray("game_ids");if(rows==null)rows=new JSONArray();
        if(ids!=null)for(int i=0;i<ids.length();i++){int id=ids.optInt(i);boolean found=false;for(int j=0;j<rows.length();j++)if(rows.getJSONObject(j).optInt("gameId")==id)found=true;if(found)continue;JSONObject game=brightRequest(new JSONObject().put("op","raConquistas").put("usuario",name).put("gameId",id),t,c);JSONArray a=game.getJSONArray("lista");int got=0,hard=0;for(int k=0;k<a.length();k++){if(a.getJSONObject(k).optBoolean("got"))got++;if(a.getJSONObject(k).optBoolean("hardcore"))hard++;}game.put("total",a.length()).put("desbloqueadas",got).put("hardcore",hard);rows.put(game);}
        JSONArray hidden=collection.optJSONArray("hidden_game_ids"),visible=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject g=rows.getJSONObject(i);boolean hide=false;for(int j=0;hidden!=null&&j<hidden.length();j++)if(hidden.optInt(j)==g.optInt("gameId"))hide=true;if(!hide)visible.put(g);}rows=visible;
        return new JSONArray().put(new JSONObject().put("profile",profile).put("jogos",rows).put("collection",collection).put("usuario",name));
    },cb);}
