    public void pushToken(String device,Callback callback){if(device.length()<32||device.length()>4096){callback.done(null,"Token inválido.");return;}execute((user,token,config)->write("/rest/v1/clt_android_push_tokens?on_conflict=user_id,token&select=user_id","POST",new JSONObject().put("user_id",user).put("token",device).put("updated_at",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'",java.util.Locale.ROOT){{setTimeZone(java.util.TimeZone.getTimeZone("UTC"));}}.format(new java.util.Date())),token,config),callback);}
    public void coverPosition(int x,int y,int zoom,Callback callback){if(x<0||x>100||y<0||y>100||zoom<25||zoom>250){callback.done(null,"Posição inválida.");return;}execute((user,token,config)->{JSONObject p=get("/rest/v1/perfis?select=banner_url&id=eq."+user+"&limit=1",token,config).getJSONObject(0);String url=p.optString("banner_url","");if(url.isEmpty()||url.equals("null"))throw new IOException("Adicione uma capa primeiro.");url=url.split("#",2)[0]+"#bc-cover="+x+","+y+","+zoom;return write("/rest/v1/perfis?id=eq."+user+"&select=id,banner_url","PATCH",new JSONObject().put("banner_url",url),token,config);},callback);}
    public void saveHighlights(JSONArray games,JSONArray achievements,int title,Callback callback){if(games.length()>8||achievements.length()>4){callback.done(null,"Selecione até 8 jogos e 4 conquistas.");return;}execute((user,token,config)->{JSONObject p=get("/rest/v1/perfis?select=nome,bio,banner_url,status_personalizado&id=eq."+user+"&limit=1",token,config).getJSONObject(0);return write("/rest/v1/rpc/salvar_personalizacao_perfil_clt","POST",new JSONObject().put("p_nome",p.opt("nome")).put("p_bio",p.opt("bio")).put("p_banner_url",p.opt("banner_url")).put("p_status",p.optString("status_personalizado","online")).put("p_titulo_destaque_nivel",title).put("p_jogos_destaque",games).put("p_conquistas_destaque",achievements),token,config);},callback);}
    public void confirmEmailChange(String address,String code,Callback cb){execute((user,token,config)->{
        JSONObject before=NativeAuthFlow.request("user","GET",new JSONObject(),token);
        if(!user.equals(before.optString("id")))throw new IOException("Sua sessão mudou.");
        String email=address.trim().toLowerCase(java.util.Locale.ROOT),otp=code.trim(),pending=before.optString("new_email","");
        if(!EmailChangePolicy.allowed(email,otp,before.optString("email"),pending))throw new IOException("Informe o endereço atual ou novo que recebeu este código numérico. É necessário ter uma troca pendente.");
        JSONObject reply=NativeAuthFlow.request("verify","POST",new JSONObject().put("email",email).put("token",otp).put("type","email_change"),null);
        String temporary=reply.optString("access_token","");if(!temporary.isEmpty())try{NativeAuthFlow.request("logout?scope=local","POST",new JSONObject(),temporary);}catch(Exception ignored){}
        JSONObject after=NativeAuthFlow.request("user","GET",new JSONObject(),token);
        if(!user.equals(after.optString("id")))throw new IOException("Sua sessão mudou.");
        boolean complete=pending.equalsIgnoreCase(after.optString("email"))&&after.optString("new_email","").isEmpty();
        android.content.SharedPreferences prefs=SessionPreferences.get(context);
        if(complete&&user.equals(prefs.getString("user_id",""))&&token.equals(prefs.getString("access_token","")))prefs.edit().putString("user_email",after.optString("email")).apply();
        return new JSONArray().put(new JSONObject().put("complete",complete).put("email",after.optString("email")).put("current",before.optString("email")));
    },cb);}
    public void updateAuth(boolean password,String value,String current,Callback callback){execute((user,token,config)->{
        JSONObject fields=new JSONObject().put(password?"password":"email",value);
        if(password)fields.put("current_password",current);
        HttpURLConnection conn=(HttpURLConnection)new URL(config[0]+"/auth/v1/user").openConnection();
        try{
            conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(12000);conn.setReadTimeout(12000);conn.setRequestMethod("PUT");conn.setDoOutput(true);conn.setRequestProperty("apikey",config[1]);conn.setRequestProperty("Authorization","Bearer "+token);conn.setRequestProperty("Content-Type","application/json");
            try(OutputStream out=conn.getOutputStream()){out.write(fields.toString().getBytes(StandardCharsets.UTF_8));}
            int status=conn.getResponseCode();if(status<200||status>=300)throw new IOException("Alteração não confirmada (HTTP "+status+"). Confira sua senha atual, sessão e os requisitos da conta.");
            JSONObject owner=new JSONObject(read(conn.getInputStream()));if(!user.equals(owner.optString("id")))throw new IOException("Resposta inválida.");
            if(password)try{AuthRevocation.revoke(config[0],config[1],token,"others");}
            catch(Exception e){throw new IOException("A senha foi alterada, mas não foi possível confirmar a saída dos outros dispositivos. Tente novamente usando a nova senha.");}
            return new JSONArray().put(owner);
        }finally{conn.disconnect();}
    },callback);}
    public void stickers(Callback callback){execute((user,token,config)->get("/rest/v1/clt_account_stickers?select=id,name,path&user_id=eq."+encode(user)+"&order=created_at.desc&limit=60",token,config),callback);}
    private byte[] stickerBytes(String path,String user,String token,String[] config)throws Exception{if(!path.matches(java.util.regex.Pattern.quote(user)+"/sticker-[a-zA-Z0-9-]+\\.(png|jpg|webp)"))throw new IOException("Figurinha inválida.");HttpURLConnection conn=(HttpURLConnection)new URL(config[0]+"/storage/v1/object/authenticated/chat-media/"+path).openConnection();try{conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(12000);conn.setReadTimeout(15000);conn.setRequestProperty("Authorization","Bearer "+token);if(conn.getResponseCode()!=200)throw new IOException("Não foi possível carregar a figurinha.");String mime=conn.getContentType();if(mime==null||!mime.matches("image/(png|jpeg|webp)"))throw new IOException("Formato inválido.");try(InputStream in=conn.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))!=-1){if(out.size()+n>5*1024*1024)throw new IOException("Figurinha maior que 5 MB.");out.write(chunk,0,n);}return out.toByteArray();}}finally{conn.disconnect();}}
    private void uploadChat(byte[] bytes,String path,String mime,String token)throws Exception{uploadModerated(bytes,"chat-media",path,mime,token);}
    private void uploadModerated(byte[] bytes,String bucket,String path,String mime,String token)throws Exception{if(!java.util.Arrays.asList("chat-media","group-chat-media","group-avatars").contains(bucket))throw new IOException("Destino inválido.");if(!token.equals(SessionPreferences.get(context).getString("access_token","")))throw new IOException("Sua sessão mudou.");HttpURLConnection conn=(HttpURLConnection)new URL(NativeBackend.ORIGIN+"/api/media/upload?bucket="+bucket+"&path="+encode(path)).openConnection();try{conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(12000);conn.setReadTimeout(60000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Authorization","Bearer "+token);conn.setRequestProperty("Content-Type",mime);conn.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=conn.getOutputStream()){out.write(bytes);}int code=conn.getResponseCode();if(code!=200)throw new IOException("Imagem não aprovada ou envio indisponível (HTTP "+code+").");JSONObject response=new JSONObject(read(conn.getInputStream()));JSONObject data=response.optJSONObject("data");if(data==null||!path.equals(data.optString("path")))throw new IOException("Envio sem confirmação.");}finally{conn.disconnect();}}
    public void saveSticker(android.net.Uri uri,String name,Callback callback){execute((user,token,config)->{android.graphics.Bitmap bitmap=ProfileImages.decode(context,uri);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);bitmap.recycle();byte[] bytes=out.toByteArray();if(bytes.length>5*1024*1024)throw new IOException("A figurinha precisa ter até 5 MB.");String path=user+"/sticker-"+java.util.UUID.randomUUID()+".png";uploadChat(bytes,path,"image/png",token);return write("/rest/v1/clt_account_stickers?select=id,name,path","POST",new JSONObject().put("id",java.util.UUID.randomUUID().toString()).put("user_id",user).put("name",name).put("filename","figurinha.png").put("path",path),token,config);},callback);}
    public void sendSticker(String friend,String stickerId,Callback callback){execute((user,token,config)->{validId(friend);if(!stickerId.matches("[a-zA-Z0-9:_-]{1,180}"))throw new IOException("Figurinha inválida.");JSONArray allowed=get("/rest/v1/amigos?select=amigo_id&user_id=eq."+user+"&amigo_id=eq."+friend+"&limit=1",token,config);if(allowed.length()==0)throw new IOException("Conversa indisponível.");JSONArray stickers=get("/rest/v1/clt_account_stickers?select=path&user_id=eq."+user+"&id=eq."+encode(stickerId)+"&limit=1",token,config);if(stickers.length()!=1)throw new IOException("Figurinha indisponível.");String original=stickers.getJSONObject(0).optString("path");byte[] bytes=stickerBytes(original,user,token,config);String ext=original.substring(original.lastIndexOf('.')+1),path=user+"/"+java.util.UUID.randomUUID()+"."+ext;uploadChat(bytes,path,ext.equals("jpg")?"image/jpeg":"image/"+ext,token);return write("/rest/v1/clt_chat_messages?select=id,remetente_id,texto,midia_url,created_at","POST",new JSONObject().put("remetente_id",user).put("destinatario_id",friend).put("texto",JSONObject.NULL).put("midia_url",path),token,config);},callback);}
    public void profileLibrary(Callback callback){execute((user,token,config)->{JSONArray all=new JSONArray();for(int offset=0;offset<20000;offset+=250){JSONArray page=get("/rest/v1/itens?select=id,nome,categoria,status,horas,nota,conquistas,plataforma,generos,tipo,capa,steam_appid,ano,loja,data,updated_at&user_id=eq."+encode(user)+"&order=id.asc&limit=250&offset="+offset,token,config);for(int i=0;i<page.length();i++)all.put(page.getJSONObject(i));if(page.length()<250)return all;}throw new IOException("Biblioteca muito extensa. O resumo não foi calculado parcialmente.");},callback);}

    public void ranking(Callback callback){execute((user,token,config)->{try{return write("/rest/v1/rpc/clt_progression_v2","POST",new JSONObject(),token,config);}catch(IOException error){if(error.getMessage()==null||!error.getMessage().contains("HTTP 404"))throw error;return write("/rest/v1/rpc/ranking_clt","POST",new JSONObject(),token,config);}},callback);}
    public void missions(boolean weekly,Callback callback){execute((user,token,config)->{
        try{return write("/rest/v1/rpc/clt_missions_v2","POST",new JSONObject(),token,config);}catch(IOException error){if(error.getMessage()==null||!error.getMessage().contains("HTTP 404"))throw error;}
        java.util.List<String> selected=null;String missionPeriod=null;
        if(weekly){
            boolean v2=false;
            try {JSONArray version=write("/rest/v1/rpc/missoes_clt_versao","POST",new JSONObject(),token,config);v2=version.length()>0&&version.getJSONObject(0).optInt("value")>=2;}
            catch(IOException error){if(error.getMessage()==null||!error.getMessage().contains("HTTP 404"))throw error;}
            selected=MissionPolicy.weekly(v2);missionPeriod=MissionPolicy.period(true,java.util.Calendar.getInstance());
            write("/rest/v1/rpc/preparar_missoes_clt","POST",new JSONObject().put("p_periodo",missionPeriod).put("p_missoes",new JSONArray(selected)),token,config);
        }
        JSONArray rows=write("/rest/v1/rpc/missoes_clt","POST",new JSONObject(),token,config);
        if(!weekly)return rows;
        JSONArray current=new JSONArray();java.util.Set<String> seen=new java.util.HashSet<>();
        for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&missionPeriod.equals(row.optString("periodo"))&&selected.contains(row.optString("missao_id"))&&seen.add(row.optString("missao_id")))current.put(row);}
        if(current.length()!=3)throw new IOException("O servidor não confirmou as 3 missões semanais. Atualize o perfil para tentar novamente.");
        return current;
    },callback);}
    public void claimMission(String id,Callback callback){if(id!=null&&id.matches("[0-9a-fA-F-]{36}")){execute((user,token,config)->write("/rest/v1/rpc/clt_claim_mission_v2","POST",new JSONObject().put("p_id",id),token,config),callback);return;}if(id==null||!id.matches("[1-9][0-9]{0,15}")){callback.done(null,"Missão inválida.");return;}execute((user,token,config)->write("/rest/v1/rpc/resgatar_missao_clt","POST",new JSONObject().put("p_id",Long.parseLong(id)),token,config),callback);}
    private JSONArray feedState(JSONArray rows,String user,String token,String[] config)throws Exception{if(rows.length()==0)return rows;String ids=ids(rows,"id");JSONArray likes=get("/rest/v1/clt_post_likes?select=post_id,user_id&post_id=in."+encode(ids)+"&limit=10000",token,config);JSONArray comments=get("/rest/v1/clt_post_comments?select=post_id&post_id=in."+encode(ids)+"&limit=10000",token,config);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String id=row.optString("id");int count=0,cc=0;boolean mine=false;for(int k=0;k<likes.length();k++){JSONObject l=likes.getJSONObject(k);if(id.equals(l.optString("post_id"))){count++;mine|=user.equals(l.optString("user_id"));}}for(int k=0;k<comments.length();k++)if(id.equals(comments.getJSONObject(k).optString("post_id")))cc++;row.put("_like_count",count).put("_liked",mine).put("_comment_count",cc);}return rows;}
