    public void updateLibraryItem(JSONObject item,boolean media,JSONObject draft,Callback cb){
        try{validateSteamId(draft);CatalogDraftInput.validate(draft.optString("nome"),draft.optString("ano"),draft.optString("generos"),draft.optString("inicio"),draft.optString("data"),draft.optString("review"));ItemInfoInput.validate(draft.optString("nome"),draft.optString("plataforma"),draft.optString("loja"),draft.optString("ano"),draft.optString("prioridade"),draft.optString("tempo_est"),draft.optString("conquistas"),draft.optString("generos"),draft.optString("preco"));ItemEditInput.validate(item.optString("id"),draft.optString("status"),draft.optString("nota"),media||draft.optString("horas").isEmpty()?null:GameInput.hours(draft.optString("horas")),draft.optString("review"));if(media){if(draft.optString("onde").length()>80||draft.optString("duracao").length()>80||draft.optString("tipo").length()>80)throw new IllegalArgumentException("Informações de mídia inválidas.");}else if(!draft.optString("tempo_est").isEmpty())GameInput.hours(draft.optString("tempo_est"));}catch(IllegalArgumentException e){cb.done(null,e.getMessage());return;}
        execute((user,token,config)->{String cover=draft.optString("capa");if(!CoverEditPolicy.allowed(cover,item.optString("capa"),user,config[0]))throw new IOException("Use uma capa do catálogo ou uma imagem enviada pelo celular.");JSONObject fields=new JSONObject();for(String key:new String[]{"nome","status","nota","review","capa"})fields.put(key,draft.optString(key));for(String key:new String[]{"ano","inicio","data"})fields.put(key,draft.optString(key).isEmpty()?JSONObject.NULL:draft.optString(key));JSONArray genres=new JSONArray();for(String g:draft.optString("generos").split(","))if(!g.trim().isEmpty())genres.put(g.trim());fields.put("generos",genres);if(media){for(String key:new String[]{"tipo","onde","duracao"})fields.put(key,draft.optString(key));}else{if(draft.has("steam_appid"))fields.put("steam_appid",draft.optString("steam_appid").isEmpty()?JSONObject.NULL:draft.optLong("steam_appid"));for(String key:new String[]{"plataforma","prioridade"})fields.put(key,draft.optString(key));for(String key:new String[]{"horas","tempo_est","conquistas"})fields.put(key,draft.optString(key).isEmpty()?JSONObject.NULL:ItemInfoInput.number(draft.optString(key)));}
            JSONArray result=write(itemTarget(item.optString("id"),media,item.isNull("updated_at")?null:item.optString("updated_at"),user)+"&select=id,nome,status,nota,capa,tipo,onde,duracao,ano,inicio,data,plataforma,loja,prioridade,tempo_est,conquistas,generos,horas,updated_at","PATCH",fields,token,config);result.getJSONObject(0).put("review",draft.optString("review")).put("preco",fields.opt("preco"));return result;
        },cb);
    }
    public void uploadItemCover(JSONObject item,boolean media,android.net.Uri uri,Callback cb){execute((user,token,config)->{JSONArray allowed=get(itemTarget(item.optString("id"),media,item.isNull("updated_at")?null:item.optString("updated_at"),user)+"&select=id&limit=1",token,config);if(allowed.length()!=1)throw new IOException("Atualize este título antes de trocar a capa.");android.graphics.Bitmap bitmap=ProfileImages.decode(context,uri);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,88,out);bitmap.recycle();String path=user+"/"+java.util.UUID.randomUUID()+".jpg";JSONObject reply=FeedMedia.request(NativeBackend.ORIGIN+"/api/media/upload?bucket=avatars&path="+encode(path),"POST",okhttp3.RequestBody.create(out.toByteArray(),okhttp3.MediaType.get("image/jpeg")),token);JSONObject data=reply.optJSONObject("data");if(data==null||!path.equals(data.optString("path"))||!reply.isNull("error"))throw new IOException("A capa não recebeu confirmação da moderação.");return new JSONArray().put(new JSONObject().put("url",config[0]+"/storage/v1/object/public/avatars/"+path));},cb,MEDIA_QUEUE);}
    private void friendAccess(String friend,String user,String token,String[] config)throws Exception{validId(friend);validId(user);if(get("/rest/v1/amigos?select=amigo_id&user_id=eq."+user+"&amigo_id=eq."+friend+"&limit=1",token,config).length()!=1)throw new IOException("Este perfil não está disponível para sua conta.");write("/rest/v1/rpc/perfil_detalhes_autorizado","POST",new JSONObject().put("p_perfil_id",friend),token,config);}
    public void friendProfile(String friend,Callback cb){execute((user,token,config)->{friendAccess(friend,user,token,config);JSONArray rows=get("/rest/v1/perfis?select=id,nome,slug,bio,status_personalizado,avatar_url,banner_url,steam_id,jogos_destaque,conquistas_destaque&id=eq."+encode(friend)+"&limit=1",token,config);if(rows.length()!=1)throw new IOException("Perfil indisponível pelas regras de privacidade.");return rows;},cb);}
    public void friendLibrary(String friend,Callback cb){execute((user,token,config)->{friendAccess(friend,user,token,config);JSONArray all=new JSONArray();for(int offset=0;offset<20000;offset+=250){JSONArray page=get("/rest/v1/itens?select=id,nome,categoria,status,nota,capa,tipo,onde,duracao,ano,inicio,data,plataforma,loja,horas,tempo_est,prioridade,conquistas,generos,steam_appid&user_id=eq."+encode(friend)+"&order=id.asc&limit=250&offset="+offset,token,config);for(int i=0;i<page.length();i++)all.put(page.getJSONObject(i).put("_readonly",true));if(page.length()<250)return all;}throw new IOException("Biblioteca extensa demais para carregar completamente.");},cb);}
    public void friendSteam(String friend,Callback cb){execute((user,token,config)->{friendAccess(friend,user,token,config);JSONArray profiles=get("/rest/v1/perfis?select=steam_id&id=eq."+encode(friend)+"&limit=1",token,config);String id=profiles.length()==0?"":profiles.getJSONObject(0).optString("steam_id");if(!id.matches("[0-9]{17}"))return new JSONArray().put(new JSONObject().put("connected",false));return new JSONArray().put(steamRequest("jogos",id,token,config).put("connected",true));},cb,STEAM_QUEUE);}
    public void updateItemInfo(JSONObject item,boolean media,String status,String rating,Double hours,String review,String[] info,Callback callback){try{ItemEditInput.validate(item.optString("id"),status,rating,hours,review);if(info.length!=9)throw new IllegalArgumentException("Informações inválidas.");ItemInfoInput.validate(info[0],info[1],info[2],info[3],info[4],info[5],info[6],info[7],info[8]);}catch(IllegalArgumentException e){callback.done(null,e.getMessage());return;}execute((user,token,config)->{JSONObject fields=new JSONObject().put("nome",info[0].trim()).put("status",status).put("nota",rating.isEmpty()?JSONObject.NULL:rating).put("review",review).put("plataforma",info[1]).put("loja",info[2]).put("ano",info[3].isEmpty()?JSONObject.NULL:info[3]).put("prioridade",info[4]).put("tempo_est",info[5]).put("conquistas",info[6].isEmpty()?JSONObject.NULL:ItemInfoInput.number(info[6])).put("preco",info[8].isEmpty()?JSONObject.NULL:ItemInfoInput.number(info[8]));JSONArray genres=new JSONArray();for(String genre:info[7].split(","))if(!genre.trim().isEmpty())genres.put(genre.trim());fields.put("generos",genres);if(!media)fields.put("horas",hours==null?JSONObject.NULL:hours);JSONArray saved=write(itemTarget(item.optString("id"),media,item.isNull("updated_at")?null:item.optString("updated_at"),user)+"&select=id,nome,status,nota,plataforma,loja,ano,prioridade,tempo_est,conquistas,generos,horas,updated_at","PATCH",fields,token,config);saved.getJSONObject(0).put("review",review).put("preco",fields.opt("preco"));return saved;},callback);}
    private static String itemTarget(String id,boolean media,String expected,String user)throws Exception{
        if(!ItemEditInput.validId(id)||expected!=null&&!expected.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.]+(?:Z|[+-][0-9]{2}:[0-9]{2})"))throw new IOException("Atualize a biblioteca antes de alterar este título.");
        return "/rest/v1/itens?id=eq."+encode(id)+"&user_id=eq."+encode(user)+"&categoria=eq."+(media?"filmes":"jogos")+"&updated_at="+(expected==null?"is.null":"eq."+encode(expected));
    }
    private JSONArray write(String path,String method,JSONObject fields,String token,String[] config)throws Exception{
        if(!token.equals(SessionPreferences.get(context).getString("access_token","")))throw new IOException("Sua sessão mudou.");HttpURLConnection conn=(HttpURLConnection)new URL(config[0]+path).openConnection();
        try{conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(12000);conn.setReadTimeout(12000);conn.setRequestMethod(method);conn.setDoOutput(fields!=null);conn.setRequestProperty("apikey",config[1]);conn.setRequestProperty("Authorization","Bearer "+token);conn.setRequestProperty("Content-Type","application/json");conn.setRequestProperty("Prefer",(path.startsWith("/rest/v1/clt_android_push_tokens")||path.startsWith("/rest/v1/clt_chat_group_reads"))?"resolution=merge-duplicates,return=representation":"return=representation");if(fields!=null)try(OutputStream out=conn.getOutputStream()){out.write(fields.toString().getBytes(StandardCharsets.UTF_8));}int code=conn.getResponseCode();if(code<200||code>=300){String machineCode="";InputStream errorStream=conn.getErrorStream();if(errorStream!=null)try{JSONObject detail=new JSONObject(read(errorStream));machineCode=detail.optString("code",detail.optString("error_code",""));}catch(JSONException ignored){}throw new IOException(ApiErrorPolicy.message(machineCode,code));}String body=read(conn.getInputStream()).trim();JSONArray result;if(path.startsWith("/rest/v1/rpc/")&&!body.startsWith("[")){result=new JSONArray();if(body.startsWith("{"))result.put(new JSONObject(body));else if(!body.isEmpty()&&!body.equals("null"))result.put(new JSONObject().put("value",new org.json.JSONTokener(body).nextValue()));}else result=new JSONArray(body);if(result.length()==0&&"DELETE".equals(method)&&(path.startsWith("/rest/v1/clt_post_likes?")||path.startsWith("/rest/v1/clt_chat_reactions?")||path.startsWith("/rest/v1/clt_chat_group_reactions?")))return new JSONArray().put(new JSONObject().put("deleted",true));if(result.length()==0&&(path.startsWith("/rest/v1/notificacoes?")||("PATCH".equals(method)&&path.startsWith("/rest/v1/clt_chat_messages?")&&path.contains("&lida=eq.false"))))return new JSONArray().put(new JSONObject().put("done",true));if(result.length()==0&&!path.startsWith("/rest/v1/rpc/"))throw new IOException("Os dados mudaram, foram removidos ou não estão acessíveis. Atualize a biblioteca antes de tentar novamente.");return result;}catch(java.net.SocketTimeoutException e){throw new IOException("A resposta demorou. Atualize antes de reenviar; os dados podem ter sido salvos.");}finally{conn.disconnect();}
    }
    public void addGame(String rawName,String platform,int status,double hours,String cover,Callback callback){
        final String name;try{name=GameInput.name(rawName);if(status<0||status>=GameInput.STATUSES.length||(Double.isNaN(hours)||Double.isInfinite(hours))||hours<0||hours>100000)throw new IllegalArgumentException("Dados inválidos.");}catch(IllegalArgumentException e){callback.done(null,e.getMessage());return;}
        final String safeCover=CoverPolicy.publicUrl(cover)?cover:"";
        execute((user,token,config)->{
            validId(user);JSONArray existing=get("/rest/v1/itens?select=id&user_id=eq."+encode(user)+"&categoria=eq.jogos&nome=eq."+encode(name)+"&limit=1",token,config);if(existing.length()>0)throw new IOException("Este jogo já está na sua biblioteca.");
            if(!token.equals(SessionPreferences.get(context).getString("access_token","")))throw new IOException("Sua sessão mudou.");
            HttpURLConnection conn=(HttpURLConnection)new URL(config[0]+"/rest/v1/itens?select=id,nome,status,plataforma,horas,nota,capa,steam_appid").openConnection();
            try{conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(12000);conn.setReadTimeout(12000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("apikey",config[1]);conn.setRequestProperty("Authorization","Bearer "+token);conn.setRequestProperty("Content-Type","application/json");conn.setRequestProperty("Prefer","return=representation");
                byte[] data=new JSONObject().put("user_id",user).put("categoria","jogos").put("nome",name).put("plataforma",platform).put("status",GameInput.STATUSES[status]).put("horas",hours).put("capa",safeCover).put("generos",new JSONArray()).toString().getBytes(StandardCharsets.UTF_8);try(OutputStream out=conn.getOutputStream()){out.write(data);}int code=conn.getResponseCode();if(code==401||code==403)throw new IOException("Sua conta não permitiu salvar. Confira a sessão.");if(code<200||code>=300)throw new IOException("Cadastro sem confirmação (HTTP "+code+"). Atualize a biblioteca antes de tentar novamente.");JSONArray result=new JSONArray(read(conn.getInputStream()));if(result.length()==0)throw new IOException("Cadastro sem confirmação. Atualize antes de tentar novamente.");return result;
            }catch(java.net.SocketTimeoutException e){throw new IOException("O cadastro demorou. Atualize a biblioteca antes de reenviar; o jogo pode ter sido salvo.");}finally{conn.disconnect();}
        },callback);
    }

