    public void groupPhoto(String group,android.net.Uri uri,Callback cb){execute((u,t,c)->{groupAccess(group,u,true,t,c);android.graphics.Bitmap image=ProfileImages.decode(context,uri);int edge=Math.min(image.getWidth(),image.getHeight());android.graphics.Bitmap crop=android.graphics.Bitmap.createBitmap(image,(image.getWidth()-edge)/2,(image.getHeight()-edge)/2,edge,edge);android.graphics.Bitmap scaled=android.graphics.Bitmap.createScaledBitmap(crop,512,512,true);ByteArrayOutputStream bytes=new ByteArrayOutputStream();scaled.compress(android.graphics.Bitmap.CompressFormat.JPEG,88,bytes);if(scaled!=crop&&scaled!=image)scaled.recycle();if(crop!=image)crop.recycle();image.recycle();String path=group+"/"+java.util.UUID.randomUUID()+".jpg";uploadModerated(bytes.toByteArray(),"group-avatars",path,"image/jpeg",t);return write("/rest/v1/clt_chat_groups?id=eq."+group+"&select=id,foto_path","PATCH",new JSONObject().put("foto_path",path),t,c);},cb);}
    public void groupMessages(String group,int offset,Callback cb){execute((u,t,c)->{groupAccess(group,u,false,t,c);JSONArray rows=get("/rest/v1/clt_chat_group_messages?select=id,group_id,remetente_id,texto,midia_path,created_at&group_id=eq."+group+"&order=created_at.desc,id.desc&limit=50&offset="+Math.max(0,offset),t,c);for(int i=0;i<rows.length();i++)rows.getJSONObject(i).put("user_id",rows.getJSONObject(i).optString("remetente_id"));withAuthors(rows,t,c);if(rows.length()>0){JSONArray reactions=get("/rest/v1/clt_chat_group_reactions?select=message_id,user_id,emoji&message_id=in."+encode(ids(rows,"id"))+"&limit=10000",t,c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);JSONArray own=new JSONArray();for(int j=0;j<reactions.length();j++)if(row.optString("id").equals(reactions.getJSONObject(j).optString("message_id")))own.put(reactions.getJSONObject(j));row.put("_reactions",own);}}return rows;},cb);}
