    public void chatUnread(Callback cb){execute((u,t,c)->{JSONObject privateCounts=new JSONObject(),groupCounts=new JSONObject();JSONArray incoming=get("/rest/v1/clt_chat_messages?select=remetente_id&destinatario_id=eq."+u+"&lida=eq.false&order=id.asc&limit=1000",t,c);int total=0;for(int offset=0;;offset+=1000){if(offset>0)incoming=get("/rest/v1/clt_chat_messages?select=remetente_id&destinatario_id=eq."+u+"&lida=eq.false&order=id.asc&limit=1000&offset="+offset,t,c);for(int i=0;i<incoming.length();i++){String sender=incoming.getJSONObject(i).getString("remetente_id");privateCounts.put(sender,privateCounts.optInt(sender)+1);total++;}if(incoming.length()<1000)break;}JSONArray memberships=get("/rest/v1/clt_chat_group_members?select=group_id&user_id=eq."+u+"&limit=1000",t,c);if(memberships.length()>0){JSONArray reads=get("/rest/v1/clt_chat_group_reads?select=group_id,last_read_at&user_id=eq."+u+"&limit=1000",t,c);for(int i=0;i<memberships.length();i++){String group=memberships.getJSONObject(i).getString("group_id");validId(group);String since="1970-01-01T00:00:00Z";for(int j=0;j<reads.length();j++)if(group.equals(reads.getJSONObject(j).optString("group_id")))since=reads.getJSONObject(j).optString("last_read_at",since);int n=count("/rest/v1/clt_chat_group_messages?group_id=eq."+group+"&remetente_id=neq."+u+"&created_at=gt."+encode(since),t,c);groupCounts.put(group,n);total+=n;}}return new JSONArray().put(new JSONObject().put("private",privateCounts).put("groups",groupCounts).put("total",total));},cb);}
    public void chatRead(String friend,String through,Callback cb){execute((u,t,c)->{validId(friend);if(MessageTime.epoch(through)<=0)throw new IOException("Data inválida.");return write("/rest/v1/clt_chat_messages?remetente_id=eq."+friend+"&destinatario_id=eq."+u+"&lida=eq.false&created_at=lte."+encode(through)+"&select=id","PATCH",new JSONObject().put("lida",true),t,c);},cb);}
    public void groupRead(String group,String through,Callback cb){execute((u,t,c)->{groupAccess(group,u,false,t,c);if(MessageTime.epoch(through)<=0)throw new IOException("Data inválida.");JSONArray prior=get("/rest/v1/clt_chat_group_reads?select=last_read_at&group_id=eq."+group+"&user_id=eq."+u+"&limit=1",t,c);if(prior.length()>0&&MessageTime.epoch(prior.getJSONObject(0).optString("last_read_at"))>=MessageTime.epoch(through))return prior;return write("/rest/v1/clt_chat_group_reads?on_conflict=group_id,user_id&select=group_id","POST",new JSONObject().put("group_id",group).put("user_id",u).put("last_read_at",through),t,c);},cb);}
    public void searchPeople(String value,Callback callback){
        final String term;try{term=FriendSearchInput.term(value);}catch(IllegalArgumentException e){callback.done(null,e.getMessage());return;}
        execute((user,token,config)->{
            JSONArray rows;
            try{rows=write("/rest/v1/rpc/buscar_usuarios_clt","POST",new JSONObject().put("p_busca",term),token,config);}
            catch(MissingRpcException e){String clean=FriendSearchInput.filter(term),pattern=encode("*"+clean+"*");rows=get("/rest/v1/perfis_publicos_clt?select=id,nome,slug,avatar_url,codigo_convite&or=(nome.ilike."+pattern+",slug.ilike."+pattern+",codigo_convite.ilike."+pattern+")&order=nome.asc&limit=25",token,config);}
            JSONArray publicRows=new JSONArray();java.util.Set<String> unique=new java.util.HashSet<>();
            for(int i=0;i<rows.length()&&publicRows.length()<25;i++){JSONObject p=rows.optJSONObject(i);if(p==null)continue;String id=p.optString("id");if(user.equals(id)||!ItemEditInput.validId(id)||!unique.add(id))continue;publicRows.put(new JSONObject().put("id",id).put("nome",p.optString("nome","Pessoa")).put("slug",p.optString("slug","")).put("avatar_url",p.optString("avatar_url","")));}return publicRows;
        },callback);
    }
